    pub fn from_scalar(ch: char) -> Option<Self> {
        let code = ch as u32;
        if code < ICON_SCALAR_START {
            return None;
        }
        Self::from_index((code - ICON_SCALAR_START) as usize)
    }

    /// Canonical id or a known alias (`home` → house).
